pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        bool ok;
        try c.assertionResolvedCallback(bytes32(uint256(0)), true) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Non-optimisticAsserter should not be able to call assertionResolvedCallback");
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    function test(address caller) public returns (bool) {
        vm.prank(caller);
        try c.assertionDisputedCallback(bytes32(0)) {
            assert(false);
            return false;
        } catch {
            assert(true);
            return true;
        }
    }
}

contract InvMutTest {
    C c;
    address public immutable oa;
    constructor(C _c) {
        c = _c;
        oa = address(c.optimisticAsserter());
    }
    function run(address caller) public payable {
        require(caller != oa);
        bool reverted;
        try c.assertionDisputedCallback(bytes32(0)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }
}

